/** Budget-only read adapter: use the same calculation version 1 as Calendar.
 * No posting is generated by a planned instalment.
 */
import {getMonthEvents} from '../../../finance.js';
const uuid=x=>typeof x==='string'&&/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(x);
const integer=(v,min,max)=>Number.isSafeInteger(v)&&v>=min&&v<=max;
const date=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&
 !v.startsWith('0000-')&&Number.isFinite(Date.parse(v+'T00:00:00Z'))&&
 new Date(v+'T00:00:00Z').toISOString().slice(0,10)===v;
const validTime=v=>typeof v==='string'&&Number.isFinite(Date.parse(v));

export function projectServerBudgetLoans(entities,month){
 const loans=[],payments=[],seen=new Set(),skipped=new Set(),posted=new Map(),ambiguous=new Set();
 for(const row of entities){
  const d=row.data;
  if(row.kind==='transaction'&&typeof d.payment_link?.loan_payment_id==='string'&&validTime(d.posted_at))
   posted.set(d.payment_link.loan_payment_id,new Date(d.posted_at).toISOString());
 }
 for(const row of entities){
  if(row.kind!=='loan')continue;
  const d=row.data;
  if(!uuid(row.id)||seen.has(row.id))throw Error('Повреждён кредитный снимок');
  seen.add(row.id);
  if(d.deleted_at!==null&&d.deleted_at!==undefined)continue;
  if(d.calculation_version!==1||typeof d.title!=='string'||!d.title.trim()||
     !integer(d.opening_minor,0,1e12)||!integer(d.payment_minor,0,1e12)||
     !integer(d.apr_basis_points,0,100000)||!integer(d.term_months,1,1200)||
     !integer(d.due_day,1,31)||!date(d.as_of_date)){
   skipped.add(row.id);continue;
  }
  loans.push({id:row.id,title:d.title,openingCents:d.opening_minor,paymentCents:d.payment_minor,
   apr:d.apr_basis_points/100,termMonths:d.term_months,dueDay:d.due_day,asOfDate:d.as_of_date});
 }
 const facts=new Set(),days=new Map();
 for(const row of entities){
  if(row.kind!=='loan_payment')continue;
  const d=row.data;
  if(!uuid(row.id)||facts.has(row.id)||!seen.has(d.loan_id))throw Error('Повреждена история кредита');
  facts.add(row.id);
  if(d.voided_at!==null&&d.voided_at!==undefined)continue;
  if(!date(d.paid_on)||!integer(d.amount_minor,1,1e12)||!['amount','term'].includes(d.strategy)){
   skipped.add(d.loan_id);continue;
  }
  // Legacy facts can omit posting timestamps. If same-day order could change
  // the calculated instalment, don't pretend a guessed order is authoritative.
  const dayKey=d.loan_id+':'+d.paid_on,group=days.get(dayKey)||[];
  group.push({strategy:d.strategy,posted:posted.get(row.id)});
  days.set(dayKey,group);
  payments.push({id:row.id,loanId:d.loan_id,date:d.paid_on,amountCents:d.amount_minor,
   strategy:d.strategy,createdAt:posted.get(row.id)??d.paid_on+'T00:00:00Z'});
 }
 for(const [key,group] of days){
  if(group.length>1&&group.some(p=>p.strategy==='amount')&&
     (group.some(p=>!p.posted)||new Set(group.map(p=>p.posted)).size!==group.length))
   ambiguous.add(key.slice(0,36));
 }
 for(const id of ambiguous)skipped.add(id);
 const available=loans.filter(l=>!skipped.has(l.id));
 const events=getMonthEvents({entries:[],settlements:[],loans:available,loanPayments:payments},month);
 return {events,missing:skipped.size>0};
}
